describe('Add and Remove Product from Cart', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.wait('@loginRequest');
    cy.get('[data-testid="shopping-cart-link"]').should('be.visible');
  });

  it('should add product to cart and update cart badge', () => {
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping-cart-badge"]').should('contain', '1');
    cy.get('[data-testid="shopping-cart-badge"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('have.attr', 'aria-disabled', 'false');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('have.text', 'Remove');
    cy.get('[data-testid="shopping-cart-badge"]').should('have.css', 'color', 'green');
  });

  it('should remove product from cart and update cart badge', () => {
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="remove-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping-cart-badge"]').should('contain', '0');
    cy.get('[data-testid="shopping-cart-badge"]').should('have.css', 'display', 'none');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('have.attr', 'aria-disabled', 'true');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('have.text', 'Add to cart');
  });
});
